"ehllo"
>>> anti_shuffle("Hello World!!!")
"Hello !!!Wdlor"
*/
string anti_shuffle(string s) 
{
    string[] words = s.split(" ");
    string[] sorted_words = words.map(word => word.sort());
    string result = "";
    for (int i = 0; i < words.length; i++)
    {
        result += sorted_words[i];
        if (i < words.length - 1)
        {
            result += " ";
        }
    }
    return result;
}

