Given an array arr of integers and a positive integer k, return a sorted array 
of length k with the maximum k numbers in arr.
Example 1:
>>> maximum([-3L, -4L, 5L], 3L)
[-4L, -3L, 5L]
Example 2:
>>> maximum([4L, -4L, 4L], 2L)
[4L, 4L]
Example 3:
>>> maximum([-3L, 2L, 1L, 2L, -1L, -2L, 1L], 1L)
[2L]
Note:
    1. The length of the array will be in the range of [1, 1000].
    2. The elements in the array will be in the range of [-1000, 1000].
    3. 0 <= k <= len(arr)
*/
long[] maximum(long[] arr, long k) 
{
    long[] result = new long[k];
    long[] heap = new long[k];
    for (long i = 0; i < k; i++)
    {
        heap[i] = arr[i];
    }
    heapify(heap);
    for (long i = k; i < arr.length; i++)
    {
        if (arr[i] > heap[0])
        {
            heap[0] = arr[i];
            heapify(heap);
        }
    }
    for (long i = 0; i < k; i++)
    {
        result[i] = heap[i];
    }
    return result;
}

void heapify(long[] heap)
{
    long n = heap.length;
    for (long i = n / 2 - 1; i >= 0; i--)
    {
        heapify(heap, i, n);
    }
}

void heapify(long[] heap, long i, long n)
{
    long largest = i;
    long left = 2 * i + 1;
    long right = 2 * i + 2;
    if (left < n && heap[left] > heap[largest])
    {
        largest = left;
    }
    if (right < n && heap[right] > heap[largest])
    {
        largest = right;
    }
    if (largest != i)
    {
        long temp = heap[i];
        heap[i] = heap[largest];
        heap[largest] = temp;
        heapify(heap, largest, n);
    }
}

void main()
{
    long[] arr = [-3L, -4L, 5L];
    long k = 3L;
    long[] result = maximum(arr, k);
    writeln(result);
}

